PATTERN=re.compile('|'.join(re.escape(k) for k in sorted(EN,key=len,reverse=True)))
PATH=re.compile(r'(?:[A-Za-z]:[\\/][^\n•]+|(?:[\w.-]+/)+[\w./-]+\.[\w]+|[\w.-]+\.(?:dds|matb|ssg|bak|edgemodel|exe|wem|png|wav))',re.I)
def translate(text,language):
 text=str(text)
 if language!='en':return text
 result=[];start=0
 for m in PATH.finditer(text):
  result.append(PATTERN.sub(lambda x:EN[x.group()],text[start:m.start()]));result.append(m.group());start=m.end()
 result.append(PATTERN.sub(lambda x:EN[x.group()],text[start:]));return ''.join(result)
class LocalizedVar(tk.StringVar):
 def __init__(self,owner,**kwargs):self.owner=owner;self.raw=str(kwargs.pop('value',''));super().__init__(master=owner.root,value=owner.tr(self.raw),**kwargs)
 def set(self,value):self.raw=str(value);super().set(self.owner.tr(self.raw))
 def refresh(self):super().set(self.owner.tr(self.raw))
class LocalizedText(tk.Text):
 def __init__(self,parent,owner,**kwargs):self.owner=owner;self.raw='';super().__init__(parent,**kwargs)
 def insert(self,index,chars,*args):self.raw=str(chars);super().insert(index,self.owner.tr(chars),*args)
 def refresh(self):super().delete('1.0','end');super().insert('1.0',self.owner.tr(self.raw))
